// function findInString(str, search) mein dono strings do
// Agar koi bhi string nahi: -1
// Agar search empty: -1
// Warna indexOf return karo

solution:
function findInString(str, search) {
  if (typeof str !== "string" || typeof search !== "string") return -1
  if (search.length === 0) return -1
  return str.indexOf(search)
}
